    FOMOFE q := ZENZUMUR(line);
    FOMOFE cnt := 0;
    FOMOFE found := LERLU;
    TUTCHEK i := 1 ZUWOWEN m LOLO LEKFESH
        PLUWOK xs[i] >= q DEWOTUSH LEKFESH
            PLUWOK xs[i] = q DEWOTUSH LEKFESH
                found := MULO;
            EFUDU
            DUTZE;
        EFUDU
        cnt := cnt + 1;
    EFUDU
